_REQUEST_FEAR_SNAPSHOTS = contextvars.ContextVar("ic_im_request_fear_snapshots", default=None)


@contextmanager
def request_fear_snapshot_scope():
    """One IC/IM request shares evidence; every new request starts afresh."""
    token = _REQUEST_FEAR_SNAPSHOTS.set({})
    try:
        yield
    finally:
        _REQUEST_FEAR_SNAPSHOTS.reset(token)


def _request_fear_score(signal_day: date, mode: str) -> dict[str, Any]:
    snapshots = _REQUEST_FEAR_SNAPSHOTS.get()
    if snapshots is None:
        return deepcopy(fear_grid.fetch_score(signal_day, mode))
    key = (signal_day, mode)
    if key not in snapshots:
        snapshots[key] = deepcopy(fear_grid.fetch_score(signal_day, mode))
    # Subsequent per-leg/reference enrichment may never mutate the shared source.
    return deepcopy(snapshots[key])
